import{z as s,x as l,o as t,c as C,q as r,j as n,D as A,d as a,s as o,S as i,b as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"报告义务","description":"","frontmatter":{"title":"报告义务","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/qo-reporting-obligations.md","filePath":"quant/qo-reporting-obligations.md","lastUpdated":1791413859000}'),p={name:"quant/qo-reporting-obligations.md"};function D(F,E,d,m,c,h){const e=l("Mermaid");return t(),C("div",null,[E[2]||(E[2]=r('<h1 id="报告义务" tabindex="-1">报告义务 <a class="header-anchor" href="#报告义务" aria-label="Permalink to &quot;报告义务&quot;">​</a></h1><div class="epigraph"><p>每份监管报告都是字段、截止与质量的三元组；迟报、漏报、错报不是三种错误，是同一种运营故障的三种表面。</p><footer>—— 据程序化交易报备、交易报告与大额持仓报告的公开制度口径整理</footer></div><p><a href="/quant/qo-compliance-monitoring">上一课</a>把红线清单搬上在线监控，让「在范围内」每天由数据确认；监控产生记录，本课写记录如何按监管口径<strong>出口</strong>。程序化交易的报备实践已在<a href="/quant/cn-programmatic-filing">程序化交易的报备实践</a>写过台账与速率画像的勾稽，红线里「报备不实本身就是红线」的口径见<a href="/quant/cn-compliance-map">合规红线与收束</a>；本课把所有报告义务当成一类对象管理：它们的共同结构，与把它们做成数据产品的方法。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>报告常被当成文案工作，交给离数据最远的人；事故也由此长出来。缺口的形态有三：<strong>口径</strong>——同一份持仓在交易系统、估值系统与报备系统里三个数，谁也不知道该报哪个；<strong>截止</strong>——报送窗口是硬时限，迟报与错报同等可见，临时凑数必然错；<strong>质量不可审计</strong>——监管问「这个字段为什么是这个值」，答不出数据从哪来。三者的共同根源：报告没有被当成<strong>数据产品</strong>——没有 schema 管理、没有数据血缘、没有迟报漏报的监控。监管侧的方向也在加重这一侧：<a href="/quant/cn-quant-regulation-history">量化监管演进</a>的趋势是把更多行为纳入定期与事件性报告，报告面只会变宽。</p><p><span class="marginnote">「数据血缘」就是给每个数字记家谱：这个值出自哪个系统的哪张表、哪个时点的快照、经过什么加工得来。监管问「这个字段为什么是这个值」时，家谱就是答案；答不出家谱的数，再对也会被按不利方向理解。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>先立谱系，再立管线。<strong>谱系</strong>按对象分：向监管的程序化报备与变更报备（见<a href="/quant/cn-programmatic-filing">程序化交易的报备实践</a>）、大额持仓报告、逐笔或逐日的交易报告（如 MiFID II 第 26 条一类的交易报告制度）、可疑交易上报（监控体系的升级出口，见<a href="/quant/qo-compliance-monitoring">合规监控体系</a>）、对托管人与投资者的定期报告。<strong>管线</strong>把每份报告拆成三元组：字段——schema 版本化，监管改字段等于新版本，旧版本归档；截止——报送日历进<a href="/quant/qo-daily-ops-checklist">交易日的操作清单</a>，按硬掩码执行；质量——每个字段有血缘记录，能反查到源系统与快照时点。</p>',8)),(t(),n(i,null,{default:A(()=>[o(e,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22%E6%BA%90%E7%B3%BB%E7%BB%9F%EF%BC%9A%E4%BA%A4%E6%98%93%20%2F%20%E6%8C%81%E4%BB%93%20%2F%20%E4%BC%B0%E5%80%BC%22%5D%20--%3E%20LIN%5B%22%E8%A1%80%E7%BC%98%E8%AE%B0%E5%BD%95%EF%BC%9A%E5%AD%97%E6%AE%B5%E5%88%B0%E6%BA%90%EF%BC%8C%E5%BF%AB%E7%85%A7%E6%97%B6%E7%82%B9%22%5D%0A%20%20LIN%20--%3E%20SCH%5B%22schema%20%E7%89%88%E6%9C%AC%EF%BC%9A%E7%9B%91%E7%AE%A1%E5%8F%A3%E5%BE%84%E5%8F%98%E6%9B%B4%E5%8D%B3%E6%96%B0%E7%89%88%E6%9C%AC%22%5D%0A%20%20SCH%20--%3E%20GEN%5B%22%E7%94%9F%E6%88%90%E4%B8%8E%E5%86%85%E9%83%A8%E5%A4%8D%E6%A0%B8%22%5D%0A%20%20GEN%20--%3E%20DEAD%7B%22%E6%88%AA%E6%AD%A2%E5%89%8D%E6%8A%A5%E9%80%81%3F%22%7D%0A%20%20DEAD%20--%3E%7C%22%E6%98%AF%22%7C%20SUB%5B%22%E6%8A%A5%E9%80%81%E5%B9%B6%E7%95%99%E5%9B%9E%E6%89%A7%22%5D%0A%20%20DEAD%20--%3E%7C%22%E5%90%A6%22%7C%20LATE%5B%22%E8%BF%9F%E6%8A%A5%E5%91%8A%E8%AD%A6%E4%B8%8E%E5%8D%87%E7%BA%A7%EF%BC%8C%E4%BA%8B%E5%90%8E%E5%BD%92%E5%9B%A0%22%5D%0A%20%20SUB%20--%3E%20MON%5B%22%E8%BF%9F%E6%8A%A5%E6%BC%8F%E6%8A%A5%E9%94%99%E6%8A%A5%E7%9B%91%E6%8E%A7%EF%BC%9A%E6%8C%89%E6%97%A5%E7%BB%9F%E8%AE%A1%22%5D%0A%20%20MON%20--%3E%20FIX%7B%22%E7%9B%91%E7%AE%A1%E8%B4%A8%E7%96%91%E6%88%96%E9%94%99%E6%8A%A5%3F%22%7D%0A%20%20FIX%20--%3E%7C%22%E6%98%AF%22%7C%20CORR%5B%22%E7%BA%A0%E9%94%99%E5%9B%9E%E5%A1%AB%EF%BC%9A%E6%B2%BF%E8%A1%80%E7%BC%98%E5%8F%8D%E6%9F%A5%22%5D%0A%20%20FIX%20--%3E%7C%22%E5%90%A6%22%7C%20RUN%5B%22%E4%B8%8B%E4%B8%80%E6%8A%A5%E5%91%8A%E6%97%A5%22%5D%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=B("h2",{id:"机制",tabindex:"-1"},[a("机制 "),B("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=B("p",null,[a("为什么必须血缘：报告的价值在可反查。监管问询的形态通常是「抽查某日某字段」，血缘断掉的报告在问询面前等于错报——答不上来的数，监管只能按不利方向理解。为什么迟报监控按日甚至按小时统计：截止是硬约束，迟报本身是监管可见的状态，漏报率 \\(\\Pr[\\text{应报未报}]\\) 要靠「应报清单」与「已报清单」的自动勾稽来压到零，两份清单不自动勾稽，漏报就是静默的。为什么纠错要写成回填而不是重报了事：错报的修正路径本身要留痕，哪一版报错、哪一版更正、差异在哪，这条链就是下一轮审计的现成材料。报告管线与"),B("a",{href:"/quant/sl-registry"},"策略台账体系"),a("的指针链同构：台账答「这个仓位凭什么」，报告管线答「这个数字从哪来」——都是让答案在任何时点可复现。")],-1)),(t(),n(i,null,{default:A(()=>[o(e,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20LR%0A%20%20Q%5B%22%E7%9B%91%E7%AE%A1%E9%97%AE%E8%AF%A2%EF%BC%9A%E6%9F%90%E6%97%A5%E6%9F%90%E5%AD%97%E6%AE%B5%E4%B8%BA%E4%BD%95%E6%98%AF%E8%BF%99%E4%B8%AA%E5%80%BC%22%5D%20--%3E%20LO%5B%22%E6%89%93%E5%BC%80%E8%A1%80%E7%BC%98%EF%BC%9A%E6%BA%90%E7%B3%BB%E7%BB%9F%E4%B8%8E%E5%BF%AB%E7%85%A7%E6%97%B6%E7%82%B9%22%5D%0A%20%20LO%20--%3E%20SNAP%5B%22%E5%8F%96%E5%87%BA%E5%BD%93%E6%97%A5%E6%BA%90%E6%95%B0%E6%8D%AE%E5%BF%AB%E7%85%A7%22%5D%0A%20%20SNAP%20--%3E%20CAL%5B%22%E6%8C%89%E5%BD%93%E6%97%B6%20schema%20%E9%87%8D%E8%B7%91%E8%AE%A1%E7%AE%97%E9%80%BB%E8%BE%91%22%5D%0A%20%20CAL%20--%3E%20CMP%7B%22%E4%B8%8E%E6%8A%A5%E9%80%81%E5%80%BC%E4%B8%80%E8%87%B4%3F%22%7D%0A%20%20CMP%20--%3E%7C%22%E4%B8%80%E8%87%B4%22%7C%20ANS%5B%22%E5%87%BA%E5%85%B7%E5%8F%AF%E5%A4%8D%E7%8E%B0%E8%AF%81%E6%98%8E%22%5D%0A%20%20CMP%20--%3E%7C%22%E4%B8%8D%E4%B8%80%E8%87%B4%22%7C%20ERR%5B%22%E5%AE%9A%E4%BD%8D%E6%96%AD%E7%82%B9%EF%BC%9Aschema%20%E7%89%88%E6%9C%AC%E6%88%96%E5%8F%A3%E5%BE%84%E5%8F%98%E6%9B%B4%22%5D%0A%20%20ERR%20--%3E%20CORR%5B%22%E6%9B%B4%E6%AD%A3%E5%9B%9E%E5%A1%AB%EF%BC%9A%E5%93%AA%E7%89%88%E9%94%99%E3%80%81%E5%93%AA%E7%89%88%E5%AF%B9%E3%80%81%E5%B7%AE%E5%BC%82%E5%9C%A8%E5%93%AA%22%5D%0A%20%20CORR%20--%3E%20ARC%5B%22%E5%85%A8%E9%93%BE%E5%BD%92%E6%A1%A3%EF%BC%8C%E4%BE%9B%E4%B8%8B%E8%BD%AE%E5%AE%A1%E8%AE%A1%22%5D%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=r('<p><span class="marginnote">「应报与已报清单自动勾稽」用数字理解：日历上本月应报 22 份，回执库收到 21 份，差集立刻亮出那 1 份漏报；靠人工回忆对账，漏报往往到监管催报才被发现——而迟报本身已经是监管可见的状态。</span></p><p><span class="marginnote">报备与速率画像必须勾稽：报备里写的申报撤单节奏，要能和实盘监控的同名指标对上；两套数对不上，「报备不实」比超速本身更难解释——这是红线清单里唯一一条由文件不一致单独触发的红线。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>各辖区的报告义务差异大、变更频繁：字段、频率、阈值以当期监管文本与自律规则为准，本课不罗列具体制度清单，也不构成法律意见。可疑交易上报的触发与表述是合规职能的判断，本课只提供管线与留痕。刻意规避报送或择时择报的技巧不在讨论范围——那不是运营优化，是违规本身。</p><p><span class="marginnote">常见误区：把报告当成「文案活」，交给离数据最远的人排版应付。实际上每份报告是一次数据发布：字段有 schema、截止是硬时限、每个值可反查。排版错了是小事，口径错了在问询面前与错报同罪。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>报告义务的共同结构是三元组：字段（schema 版本化）、截止（硬掩码进日历）、质量（血缘可反查）。</li><li>谱系五类：程序化报备、大额持仓、交易报告、可疑交易上报、对托管与投资者的定期报告。</li><li>应报与已报两份清单自动勾稽，迟报漏报按日统计；纠错写成留痕的回填。</li><li>血缘断掉的报告在问询面前等于错报；报备口径必须与实盘监控画像勾稽。</li><li>出处：据程序化交易报备、MiFID II 第 26 条类交易报告与大额持仓报告公开制度口径整理；台账口径见<a href="/quant/sl-registry">策略台账体系</a>。</li></ul>',7))])}const f=s(p,[["render",D]]);export{u as __pageData,f as default};
